/**
 * Exercise real owner-local files, immutable revision transactions and static alias refusals.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - interface Snapshot: line 26
 * - interface Workspace: line 31
 * - variable native: line 38
 * - variable files: line 46
 * - variable starter: line 52
 * - variable roots: line 57
 * - variable opened: line 58
 * - function fixture: line 59
 * - function open: line 65
 * - function changed: line 70
 * @@SYMBOL_INDEX_END
 */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { afterEach, describe, expect, it, vi } from "vitest";
import * as core from "../../src/lib/workspace";
import { PRODUCTS } from "../../src/data/products";
import { loadTopics } from "../../tools/load-topics";
import type { KnowledgeCatalog } from "../../src/lib/workspace";

interface Snapshot {
  revision: string;
  catalog: KnowledgeCatalog;
  history: { revision: string; sequence: number; current: boolean; reason: string }[];
}
interface Workspace {
  browser: string;
  snapshot(): Snapshot;
  save(base: string, catalog: KnowledgeCatalog, reason?: string): Promise<Snapshot>;
  restore(base: string, revision: string): Promise<Snapshot>;
  close(): Promise<void>;
}
const native = createRequire(import.meta.url)("../../desktop/state.cjs") as {
  openWorkspace(
    root: string,
    excluded: string[],
    validators: typeof core,
    starter: KnowledgeCatalog,
  ): Workspace;
};
const files = createRequire(import.meta.url)("../../desktop/files.cjs") as {
  readRegular(name: string, maximum: number): Buffer;
  readUtf8(name: string, maximum: number): string;
  newFile(name: string, bytes: string | Buffer): void;
  localPath(name: unknown): string;
};
const starter = core.validateCatalog({
  schemaVersion: 1,
  products: PRODUCTS,
  topics: await loadTopics(),
});
const roots: string[] = [];
const opened: Workspace[] = [];
function fixture() {
  fs.mkdirSync(".runtime", { recursive: true });
  const root = fs.mkdtempSync(path.resolve(".runtime/portal-state-"));
  roots.push(root);
  return root;
}
function open(root = path.join(fixture(), "workspace")) {
  const value = native.openWorkspace(root, [], core, starter);
  opened.push(value);
  return { root, value };
}
function changed(catalog: KnowledgeCatalog, name = "Reviewed sensor documentation") {
  const result = structuredClone(catalog);
  const topic = result.topics[0];
  if (!topic) throw new Error("Expected original corpus.");
  return core.applyTopic(result, JSON.stringify({ ...topic, title: name }), topic.id);
}
afterEach(async () => {
  vi.restoreAllMocks();
  for (const value of opened.splice(0)) await value.close();
  for (const root of roots.splice(0)) {
    if (!root.startsWith(path.resolve(".runtime") + path.sep))
      throw new Error("Invalid owned test root.");
    fs.rmSync(root, { recursive: true, force: true });
  }
});

describe("real immutable native workspace", () => {
  it("stops oversized root admission before opening or changing any file", () => {
    const root = fixture();
    for (let index = 0; index < 64; index++)
      fs.writeFileSync(path.join(root, `unrelated-${index}.txt`), `preserve-${index}`);
    const opening = vi.spyOn(fs, "openSync");
    expect(() => open(root)).toThrow(/entry budget/u);
    expect(opening).not.toHaveBeenCalled();
    opening.mockRestore();
    expect(fs.readdirSync(root)).toHaveLength(64);
    expect(fs.readFileSync(path.join(root, "unrelated-63.txt"), "utf8")).toBe("preserve-63");
  });
  it("rejects oversized revision inventory before reading any revision bytes", async () => {
    const { root, value } = open();
    await value.close();
    opened.splice(opened.indexOf(value), 1);
    const folder = path.join(root, "revisions");
    for (let index = 0; index < 51; index++)
      fs.writeFileSync(
        path.join(folder, index.toString(16).padStart(64, "0") + ".json"),
        "unread sentinel",
      );
    const actual = fs.openSync;
    let revisionReads = 0;
    vi.spyOn(fs, "openSync").mockImplementation((name, flags, mode) => {
      if (String(name).startsWith(folder + path.sep)) {
        revisionReads++;
        throw new Error("Revision bytes must not be read after directory overflow.");
      }
      return actual(name, flags, mode);
    });
    expect(() => open(root)).toThrow(/entry budget/u);
    expect(revisionReads).toBe(0);
    expect(fs.readdirSync(folder)).toHaveLength(52);
    expect(fs.existsSync(path.join(root, "owner.lock"))).toBe(false);
  });
  it("saves, reopens and restores exact catalogs without changing prior bytes", async () => {
    const { root, value } = open();
    const initial = value.snapshot(),
      record = fs.readFileSync(path.join(root, "revisions", initial.revision + ".json"));
    const next = await value.save(initial.revision, changed(initial.catalog));
    expect(next.history).toHaveLength(2);
    expect(next.catalog.topics[0]?.title).toBe("Reviewed sensor documentation");
    expect(fs.readFileSync(path.join(root, "revisions", initial.revision + ".json"))).toEqual(
      record,
    );
    await value.close();
    opened.splice(opened.indexOf(value), 1);
    const reopened = open(root).value;
    expect(reopened.snapshot()).toEqual(next);
    const restored = await reopened.restore(next.revision, initial.revision);
    expect(restored.catalog).toEqual(initial.catalog);
    expect(restored.history).toHaveLength(3);
    expect(restored.history[0]?.reason).toBe("Restored revision");
  });
  it("copies admitted catalogs and refuses a stale queued save", async () => {
    const { value } = open(),
      initial = value.snapshot();
    const draft = changed(initial.catalog);
    const first = value.save(initial.revision, draft);
    const stale = value.save(initial.revision, changed(initial.catalog, "Another review title"));
    (draft.topics[0] as { title: string }).title = "Mutation after admission";
    const saved = await first;
    expect(saved.catalog.topics[0]?.title).toBe("Reviewed sensor documentation");
    await expect(stale).rejects.toThrow(/changed/u);
    expect(value.snapshot()).toEqual(saved);
  });
  it("binds restore to the current pointer and refuses unknown identities", async () => {
    const { value } = open(),
      initial = value.snapshot();
    await expect(value.restore(initial.revision, "a".repeat(64))).rejects.toThrow(/known/u);
    const saved = await value.save(initial.revision, changed(initial.catalog));
    await expect(value.restore(initial.revision, initial.revision)).rejects.toThrow(/changed/u);
    expect(value.snapshot()).toEqual(saved);
  });
  it("does not accept saves after close begins, while waiting for the same real rename", async () => {
    const { value } = open(),
      initial = value.snapshot();
    const actual = fs.promises.rename;
    let release: (() => void) | undefined;
    const held = new Promise<void>((resolve) => {
      release = resolve;
    });
    let entered = false;
    vi.spyOn(fs.promises, "rename").mockImplementation(async (...args) => {
      entered = true;
      await held;
      return actual(...args);
    });
    const saving = value.save(initial.revision, changed(initial.catalog));
    await vi.waitFor(() => {
      expect(entered).toBe(true);
    });
    let closed = false;
    const closing = value.close().then(() => {
      closed = true;
    });
    await new Promise((resolve) => setTimeout(resolve, 20));
    expect(closed).toBe(false);
    await expect(value.save(initial.revision, initial.catalog)).rejects.toThrow(/cannot accept/u);
    release?.();
    await saving;
    await closing;
    expect(closed).toBe(true);
  });
  it("retains prior pointer, completed revision and temporary pointer when atomic replacement fails", async () => {
    const { root, value } = open(),
      initial = value.snapshot(),
      pointer = fs.readFileSync(path.join(root, "current.json"));
    vi.spyOn(fs.promises, "rename").mockRejectedValueOnce(
      new Error("Synthetic replacement failure"),
    );
    await expect(value.save(initial.revision, changed(initial.catalog))).rejects.toThrow(
      /replacement failure/u,
    );
    expect(value.snapshot().revision).toBe(initial.revision);
    expect(fs.readFileSync(path.join(root, "current.json"))).toEqual(pointer);
    expect(fs.readdirSync(path.join(root, "revisions"))).toHaveLength(2);
    expect(fs.readdirSync(root).filter((name) => name.startsWith(".current-"))).toHaveLength(1);
    await value.close();
    opened.splice(opened.indexOf(value), 1);
    expect(() => open(root)).toThrow(/Unknown workspace/u);
  });
  it("refuses corrupt immutable history and preserves it for review", async () => {
    const { root, value } = open(),
      initial = value.snapshot();
    await value.close();
    opened.splice(opened.indexOf(value), 1);
    const name = path.join(root, "revisions", initial.revision + ".json");
    fs.appendFileSync(name, " ");
    expect(() => open(root)).toThrow(/hash differs/u);
    expect(fs.existsSync(name)).toBe(true);
    expect(fs.existsSync(path.join(root, "owner.lock"))).toBe(false);
  });
  it("never adopts unknown or incomplete profile directories", () => {
    const root = fixture();
    fs.writeFileSync(path.join(root, "user-file.txt"), "preserve");
    expect(() => open(root)).toThrow(/Unknown workspace/u);
    expect(fs.readFileSync(path.join(root, "user-file.txt"), "utf8")).toBe("preserve");
    const other = fixture();
    fs.mkdirSync(path.join(other, "revisions"));
    expect(() => open(other)).toThrow(/cannot be adopted/u);
  });
  it("refuses the program directory before initialization", () => {
    const root = fixture();
    expect(() => native.openWorkspace(root, [path.dirname(root)], core, starter)).toThrow(
      /outside application/u,
    );
    expect(fs.readdirSync(root)).toEqual([]);
  });
  for (const fixed of ["owner.json", "owner.lock", "current.json"])
    it(`refuses pre-existing hardlinked ${fixed} without touching the unrelated file`, async () => {
      const { root, value } = open();
      await value.close();
      opened.splice(opened.indexOf(value), 1);
      const other = path.join(path.dirname(root), "unrelated.txt"),
        target = path.join(root, fixed);
      if (fs.existsSync(target)) fs.renameSync(target, other);
      else fs.writeFileSync(other, "unrelated-lock");
      const bytes = fs.readFileSync(other);
      fs.linkSync(other, target);
      expect(() => open(root)).toThrow(/ordinary unaliased/u);
      expect(fs.readFileSync(other)).toEqual(bytes);
    });
  it("refuses Chromium database sidecar aliases before opening Chromium", async () => {
    const { root, value } = open();
    await value.close();
    opened.splice(opened.indexOf(value), 1);
    const other = path.join(path.dirname(root), "sidecar.txt");
    fs.writeFileSync(other, "unrelated-sidecar");
    fs.linkSync(other, path.join(root, "browser-state", "Cookies-journal"));
    expect(() => open(root)).toThrow(/unsupported file/u);
    expect(fs.readFileSync(other, "utf8")).toBe("unrelated-sidecar");
  });
  it("preserves ordinary existing browser recovery files", async () => {
    const { root, value } = open();
    await value.close();
    opened.splice(opened.indexOf(value), 1);
    const file = path.join(root, "browser-state", "Cookies-journal");
    fs.writeFileSync(file, "ordinary pending recovery");
    const fresh = open(root).value;
    expect(fresh.snapshot().catalog).toEqual(starter);
    expect(fs.readFileSync(file, "utf8")).toBe("ordinary pending recovery");
  });
  it("refuses a directory or junction in a fixed file slot", async () => {
    const { root, value } = open();
    await value.close();
    opened.splice(opened.indexOf(value), 1);
    fs.unlinkSync(path.join(root, "current.json"));
    fs.mkdirSync(path.join(root, "current.json"));
    expect(() => open(root)).toThrow(/ordinary unaliased/u);
  });
  it("does not overwrite selected exports and uses strict bounded UTF-8", () => {
    const root = fixture(),
      name = path.join(root, "export.json");
    files.newFile(name, "original");
    expect(() => files.newFile(name, "changed")).toThrow();
    expect(files.readUtf8(name, 8)).toBe("original");
    expect(() => files.readRegular(name, 7)).toThrow();
    fs.writeFileSync(name, Buffer.from([0xff]));
    expect(() => files.readUtf8(name, 8)).toThrow();
  });
  it("rejects relative and non-path inputs before metadata access", () => {
    for (const value of ["relative.json", null, 7, "x\0y"])
      expect(() => files.localPath(value)).toThrow();
    if (process.platform === "win32")
      for (const value of ["\\\\server\\share\\x", "\\\\?\\C:\\data", "C:\\file:stream"])
        expect(() => files.localPath(value)).toThrow();
  });
  it("limits retained history instead of silently deleting earlier revisions", async () => {
    const { root, value } = open();
    let snapshot = value.snapshot();
    for (let index = 1; index < 50; index++)
      snapshot = await value.save(
        snapshot.revision,
        changed(snapshot.catalog, `Reviewed topic revision ${index}`),
      );
    expect(snapshot.history).toHaveLength(50);
    await expect(
      value.save(snapshot.revision, changed(snapshot.catalog, "One more review")),
    ).rejects.toThrow(/Fifty revisions/u);
    expect(fs.readdirSync(path.join(root, "revisions"))).toHaveLength(50);
  }, 20_000);
});
